<?php
$members=array_filter(managed_accounts(),function($u) {
    return (!param($_GET,'q') || mb_stripos($u['username'],param($_GET,'q'))!==false)
      && (param($_GET,'review')!=='flagged' || !preg_match('/[\p{L}\p{N}]/u',$u['username']) || str_contains($u['username'],'�'))
      && (!param($_GET,'role') || $u['role']===param($_GET,'role'))
      && (!param($_GET,'status') || (bool)$u['disabled']===(param($_GET,'status')==='disabled'));
});
usort($members,fn($a,$b)=>strcasecmp($a['username'],$b['username']));
[$members,$page,$pages,$total]=admin_page($members);
?>
<form class="admin-filter-form" action="/admin/users"><input type="search" name="q" aria-label="Search members" value="<?= e(param($_GET,'q')) ?>" placeholder="Search community members"><select name="role" aria-label="Filter role"><?php foreach([''=>'All roles','admin'=>'Administrators','member'=>'Members'] as $key=>$label): ?><option value="<?= $key ?>" <?= param($_GET,'role')===$key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select><select name="status" aria-label="Filter access"><?php foreach([''=>'All access','active'=>'Active','disabled'=>'Disabled'] as $key=>$label): ?><option value="<?= $key ?>" <?= param($_GET,'status')===$key ? 'selected' : '' ?>><?= $label ?></option><?php endforeach; ?></select><select name="review" aria-label="Filter name review"><option value="">All names</option><option value="flagged" <?= param($_GET,'review')==='flagged' ? 'selected' : '' ?>>Names needing review</option></select><button>Search members</button></form><p class="help"><?= number_format($total) ?> <?= $total===1 ? 'member' : 'members' ?>. Imported accounts can be managed before their first sign-in.</p>
<div class="table-scroll prototype-panel"><table class="member-table"><thead><tr><th>Member</th><th>Created / Last login</th><th>Activity</th><th>Publishing</th><th>Access / Role</th></tr></thead><tbody><?php foreach($members as $m): ?><tr><td><strong><?= e($m['username']) ?></strong><br><span class="help"><?= e($m['source']) ?></span><?php if (!preg_match('/[\p{L}\p{N}]/u',$m['username']) || str_contains($m['username'],'�')): ?><p class="status-pill">Name needs review</p><?php endif; ?><p class="help"><?= (int)$m['archive'] ?> archived · <?= (int)$m['uploads'] ?> uploads</p></td><td><?php render_time((int)$m['created']); ?><br><?php render_time($m['last_login'] ? (int)$m['last_login'] : null); ?></td><td><?= (int)$m['login_count'] ?> sign-ins<br><?php render_time($m['last_seen'] ? (int)$m['last_seen'] : null); ?></td><td><form action="/admin/member" method="post"><?= csrf_field() ?><input type="hidden" name="account" value="<?= e($m['key']) ?>"><input type="hidden" name="action" value="trust"><button class="quiet-button" aria-pressed="<?= $m['auto_approve'] ? 'true' : 'false' ?>"><?= $m['auto_approve'] ? 'Auto upload: on' : 'Auto upload: off' ?></button></form></td><td><strong><?= e($m['role']) ?></strong> · <?= $m['disabled'] ? 'Disabled' : 'Active' ?><?php if ($m['id']!==(int)$user['id']): ?><div class="member-actions"><?php foreach(['access'=>$m['disabled'] ? 'Enable account' : 'Disable account','role'=>$m['role']==='admin' ? 'Make member' : 'Make admin'] as $action=>$label): ?><form action="/admin/member" method="post"><?= csrf_field() ?><input type="hidden" name="account" value="<?= e($m['key']) ?>"><input type="hidden" name="action" value="<?= $action ?>"><button class="quiet-button"><?= e($label) ?></button></form><?php endforeach; ?></div><?php else: ?><p class="help">Your administrator account</p><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php admin_pagination('/admin/users',$page,$pages); ?>
